//! Broad-source confirmation collectors and actual literal-name result consumers.
#[path="custom_final_next_wave_support.rs"]mod support;
use ironsmith::{CardDefinition,GameState,PlayerId,Zone,Effect};use serde_json::Value;use std::collections::BTreeSet;
const A:PlayerId=PlayerId(0);
fn normalize(key:&str)->&str{key.strip_prefix("rev:").or_else(||key.strip_prefix("revolution:")).or_else(||key.strip_prefix("msem:")).unwrap_or(key)}
fn fixtures(waste:bool)->Vec<Value>{if waste{vec![serde_json::from_str(include_str!("../../../fixtures/custom_mechanics/revolution-waste-bound.json")).unwrap(),serde_json::from_str(include_str!("../../../fixtures/custom_mechanics/revolution-waste-outcome-consumers.json")).unwrap()]}else{vec![serde_json::from_str(include_str!("../../../fixtures/custom_mechanics/revolution-syzygy-source-complete.json")).unwrap()]}}
fn cards(waste:bool)->Vec<Value>{fixtures(waste).iter().flat_map(|data|data["mechanics"].as_array().unwrap()).flat_map(|row|row["representative_cards"].as_array().unwrap()).cloned().collect()}
fn whole(waste:bool,expected:&[&str]){let mut actual=BTreeSet::new();let mut failures=Vec::new();for card in cards(waste){let key=normalize(card["source_card_key"].as_str().unwrap_or_else(||card["id"].as_str().unwrap()));assert!(actual.insert(key.to_string()),"duplicate physical source {key}");assert_eq!(card["source_faces"].as_array().unwrap().len(),1,"whole original face evidence {key}");match support::linked_definitions(&card){Ok(routes)=>assert_eq!(routes.len(),1),Err(error)=>failures.push(format!("{key}: {error}"))}}let expected:BTreeSet<String>=expected.iter().map(|key|key.to_string()).collect();assert_eq!(actual,expected,"exact broad-confirmed physical scope");assert!(failures.is_empty(),"{} full-source failures:\n{}",failures.len(),failures.join("\n"));}
#[test]fn all_twenty_one_syzygy_sources_strict_independent_native_and_artifact(){whole(false,SYZYGY)}
#[test]fn all_thirty_three_waste_operator_observer_and_result_consumer_sources_strict_both_routes(){whole(true,WASTE)}
fn named(name:&str)->[CardDefinition;2]{let card=cards(true).into_iter().find(|card|card["name"].as_str()==Some(name)).unwrap_or_else(||panic!("missing actual source {name}"));support::definitions(&card).unwrap()}
fn plain(name:&str,text:&str)->CardDefinition{ironsmith_compiler_runtime::compile_to_runtime_definition(name,text,false).unwrap()}
fn game()->GameState{let mut game=GameState::new(vec!["A".into(),"B".into()],20);game.turn.active_player=A;game.turn.priority_player=Some(A);game.turn.phase=ironsmith::game_state::Phase::FirstMain;game.turn.step=None;game}
fn resolve_spell(game:&mut GameState,definition:&CardDefinition){let source=game.create_object_from_definition(definition,A,Zone::Stack);let mut dm=ironsmith::decision::SelectFirstDecisionMaker;let mut ctx=ironsmith::effects::EffectContext::new(source,A,&mut dm);for effect in definition.spell_effect.as_ref().unwrap().all_effects(){ironsmith::effects::execute_effect(game,effect,&mut ctx).unwrap();}}
fn nexus_guard(definition:&CardDefinition)->ironsmith::effects::ConditionalEffect{fn find(effect:&Effect,out:&mut Vec<ironsmith::effects::ConditionalEffect>){if let Some(guard)=effect.downcast_ref::<ironsmith::effects::ConditionalEffect>(){let filter=match &guard.condition{ironsmith::effect::Condition::TaggedObjectMatches(_,filter)|ironsmith::effect::Condition::TargetMatches(filter)=>Some(filter),_=>None};if let Some(filter)=filter{if filter.name.as_deref().is_some_and(|name|name.eq_ignore_ascii_case("Wastes")){assert!(filter.subtypes.is_empty(),"Wastes is a name, never an invented land subtype");out.push(guard.clone());}}}effect.visit_child_effects(&mut|child|find(child,out));}let mut found=Vec::new();for ability in &definition.abilities{if let ironsmith::ability::AbilityKind::Activated(activation)=&ability.kind{for effect in activation.effects.all_effects(){find(effect,&mut found);}}}assert_eq!(found.len(),1,"actual source must retain one explicit name predicate");found.pop().unwrap()}
#[test]fn actual_nexus_name_guard_accepts_ordinary_wastes_and_real_waste_conversion_but_not_unrelated_land(){for route in 0..2{for candidate_kind in 0..3{let mut game=game();let basic=plain("Wastes","Type: Basic Land\n{T}: Add {C}.");let original=plain("Ancient grove","Type: Land — Forest\n{T}: Add {G}.");let plains=plain("Plains","Type: Basic Land — Plains\n{T}: Add {W}.");let candidate=game.create_object_from_definition(if candidate_kind==0{&basic}else if candidate_kind==1{&original}else{&plains},A,Zone::Battlefield);let snapshot=ironsmith::snapshot::ObjectSnapshot::from_object_id(&game,candidate).unwrap();
 if candidate_kind==1{game.create_object_from_definition(&original,A,Zone::Battlefield);resolve_spell(&mut game,&named("Landscape Decay")[route]);assert_eq!(game.current_characteristics(candidate).unwrap().name.as_ref(),"Wastes");assert!(game.current_characteristics(candidate).unwrap().subtypes.is_empty());}
 game.tap(candidate);let definition=named("Neglected Nexus")[route].clone();let source=game.create_object_from_definition(&definition,A,Zone::Battlefield);let guard=nexus_guard(&definition);let tag=if let ironsmith::effect::Condition::TaggedObjectMatches(tag,_)=&guard.condition{Some(tag.clone())}else{None};let mut ctx=ironsmith::effects::EffectContext::new_default(source,A).with_targets(vec![ironsmith::effects::ResolvedTarget::Object(candidate)]);if let Some(tag)=tag{ctx.tag_object(tag,snapshot);}ironsmith::effects::execute_effect(&mut game,&Effect::new(guard),&mut ctx).unwrap();assert_eq!(game.is_tapped(candidate),candidate_kind==2,"actual parsed name guard, case {candidate_kind}");
}}}
#[test]fn actual_eldritch_growth_untaps_only_wastes_from_its_own_search_arrivals(){for route in 0..2{let mut game=game();let wastes=plain("Wastes","Type: Basic Land\n{T}: Add {C}.");let plains=plain("Plains","Type: Basic Land — Plains\n{T}: Add {W}.");let old=game.create_object_from_definition(&wastes,A,Zone::Battlefield);game.tap(old);let first=game.create_object_from_definition(&wastes,A,Zone::Library);let second=game.create_object_from_definition(&plains,A,Zone::Library);let first_stable=game.object(first).unwrap().stable_id;let second_stable=game.object(second).unwrap().stable_id;resolve_spell(&mut game,&named("Eldritch Growth")[route]);let first=game.find_object_by_stable_id(first_stable).unwrap();let second=game.find_object_by_stable_id(second_stable).unwrap();assert_eq!(game.object(first).unwrap().zone,Zone::Battlefield);assert_eq!(game.object(second).unwrap().zone,Zone::Battlefield);assert!(!game.is_tapped(first));assert!(game.is_tapped(second));assert!(game.is_tapped(old),"same name without this instruction's arrival receipt stays tapped");}}
#[test]fn broad_scope_negative_controls_are_names_not_unknown_unsupported_mechanics(){let proof:Value=serde_json::from_str(include_str!("../../../reports/custom-mechanics/older-lexical-source-confirmations.json")).unwrap();for family in proof["families"].as_array().unwrap(){let accepted:BTreeSet<_>=family["confirmed_keys"].as_array().unwrap().iter().map(|v|v.as_str().unwrap()).collect();for control in family["negative_controls"].as_array().unwrap(){assert!(!accepted.contains(control["source_card_key"].as_str().unwrap()));assert_eq!(control["verified_no_root_match_after_removing_exact_face_names"],true);}assert_eq!(family["counts"]["back_face_matches"],0);assert!(family["scanner"]["face_counts"]["nonempty_back_rules"].as_u64().unwrap()>0,"back faces genuinely audited");}}

