const SYZYGY: &[&str] = &["Architect of Ascension_SOL", "Breach Herald_SOL", "Comet Conduit_SOL", "Convergence Harmonist_SOL", "Crestfallen Colossus_SOL", "Edge of Null_SOL", "Fission Feaster_SOL", "Helia Extinguisher_SOL", "Hollow Prophet_SOL", "Horizon Blotter_SOL", "Inexorable Shepherd_SOL", "Lightless Diviner_SOL", "Myriad Crusader_SOL", "Nullblade Artisan_SOL", "Prism Catcher_SOL", "Qaraz Doomsayer_SOL", "Rift Partisan_SOL", "Shadow Caster_SOL", "Sire of Greatness_SOL", "Stardust Behemoth_SOL", "Twilight Legion_SOL"];

#[test]fn full_nexus_activation_binds_fetched_land_after_sacrifice_and_shuffle(){for route in 0..2{for fetch_wastes in [false,true]{let mut game=game();let definition=named("Neglected Nexus")[route].clone();let source=game.create_object_from_definition(&definition,A,Zone::Battlefield);let source_stable=game.object(source).unwrap().stable_id;let old=game.create_object_from_definition(&plain("Wastes","Type: Basic Land\n{T}: Add {C}."),A,Zone::Battlefield);game.tap(old);let fetched=game.create_object_from_definition(&plain(if fetch_wastes{"Wastes"}else{"Plains"},if fetch_wastes{"Type: Basic Land\n{T}: Add {C}."}else{"Type: Basic Land — Plains\n{T}: Add {W}."}),A,Zone::Library);let stable=game.object(fetched).unwrap().stable_id;
 let action=ironsmith::decision::compute_legal_actions(&game,A).unwrap().into_iter().find(|a|matches!(a,ironsmith::decision::LegalAction::ActivateAbility{source:id,..}if *id==source)).unwrap();use ironsmith::game_loop::*;let mut queue=ironsmith::triggers::TriggerQueue::new();let mut state=PriorityLoopState::new(2);let mut dm=ironsmith::decision::SelectFirstDecisionMaker;let mut progress=apply_priority_response_with_dm(&mut game,&mut queue,&mut state,&PriorityResponse::PriorityAction(action),&mut dm).unwrap();for _ in 0..64{if !state.has_pending_action(){break}let ironsmith::GameProgress::NeedsDecisionCtx(ctx)=progress else{panic!("{progress:?}")};progress=apply_decision_context_with_dm(&mut game,&mut queue,&mut state,&ctx,&mut dm).unwrap();}assert!(!state.has_pending_action());assert_eq!(game.stack.len(),1);assert_eq!(game.object(game.find_object_by_stable_id(source_stable).unwrap()).unwrap().zone,Zone::Graveyard);resolve_stack_entry_with(&mut game,&mut dm).unwrap();let fetched=game.find_object_by_stable_id(stable).unwrap();assert_eq!(game.object(fetched).unwrap().zone,Zone::Battlefield);assert_eq!(game.is_tapped(fetched),!fetch_wastes);assert!(game.is_tapped(old),"not the fetched land");}}}
